import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Закон о Гарантии Жилья","description":"","frontmatter":{},"headers":[],"relativePath":"ru/45-住房保障法.md","filePath":"ru/45-住房保障法.md","lastUpdated":null}'),d={name:"ru/45-住房保障法.md"};function e(o,t,n,h,s,u){return i(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="закон-о-гарантии-жилья" tabindex="-1">Закон о Гарантии Жилья <a class="header-anchor" href="#закон-о-гарантии-жилья" aria-label="Permalink to &quot;Закон о Гарантии Жилья&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>45</td></tr><tr><td>Модуль</td><td>Правовая система и структура управления</td></tr><tr><td>Ключевые слова</td><td>Право на жильё, Гарантированное жильё, Пространственные правовые принципы, Пригодная для жизни среда, Антиспекуляция</td></tr></tbody></table><h2 id="i-цель-законодательства-и-основные-принципы" tabindex="-1">I. Цель законодательства и основные принципы <a class="header-anchor" href="#i-цель-законодательства-и-основные-принципы" aria-label="Permalink to &quot;I. Цель законодательства и основные принципы&quot;">​</a></h2><p><em>Закон о Гарантии Жилья</em> — один из пяти вспомогательных законов Симбиотической Цивилизации Якоря. Он направлен на гарантию права на жильё всех жизней во Вселенной Хэнъюань, создание справедливой и устойчивой системы гарантии жилья, использование технологии регулирования пространственных правовых принципов для предоставления подходящих жилых пространств всем расам и предотвращение спекуляции и хищничества в жилищной сфере.</p><p>Настоящий Закон устанавливает следующие основные принципы:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Содержание</th></tr></thead><tbody><tr><td>Гарантия жилья</td><td>Каждое существо имеет право на подходящее жилое пространство; государство и цивилизация обязаны гарантировать базовые жилищные потребности</td></tr><tr><td>Приоритет общественного блага</td><td>Жильё — прежде всего предмет первой необходимости, а не спекулятивный товар; гарантированное жильё имеет атрибут общественного блага</td></tr><tr><td>Пространственная эффективность</td><td>Использование технологии регулирования пространственных правовых принципов для повышения эффективности использования пространства и расширения пригодного для жизни пространства</td></tr><tr><td>Адаптация иных рас</td><td>Предоставление адаптированных жилых пространств с учётом физиологических особенностей и жизненных привычек разных рас</td></tr><tr><td>Пригодная для жизни среда</td><td>Жилые пространства должны обладать хорошей экологической средой, инфраструктурой и общественными услугами</td></tr><tr><td>Антиспекуляция</td><td>Запрет спекулятивной наживы на жилье, предотвращение превращения жилья в инструмент хищения богатства</td></tr></tbody></table><h2 id="ii-правовые-гарантии-права-на-жилье" tabindex="-1">II. Правовые гарантии права на жильё <a class="header-anchor" href="#ii-правовые-гарантии-права-на-жилье" aria-label="Permalink to &quot;II. Правовые гарантии права на жильё&quot;">​</a></h2><p>Настоящий Закон прямо устанавливает, что право на жильё — основное право, предоставленное каждой жизни Симбиотической Конституцией, и включает:</p><ol><li><strong>Базовое право на жильё</strong>: каждое существо имеет право на жилое пространство не ниже минимального стандарта, при этом минимальный стандарт определяется с учётом размеров тела и жизненных потребностей расы.</li><li><strong>Право на заявку о гарантированном жилье</strong>: соответствующие существа имеют право подавать заявки на гарантированное жильё, условия заявки и стандарты распределения открыты и прозрачны.</li><li><strong>Право на безопасность жилья</strong>: жилые пространства должны соответствовать стандартам безопасности; аварийные и непригодные для жизни пространства не могут сдаваться или распределяться.</li><li><strong>Право на стабильность жилья</strong>: жильцы гарантированного жилья при соблюдении условий пользуются стабильным правом проживания и не могут быть произвольно выселены.</li><li><strong>Право на среду проживания</strong>: жильцы имеют право на чистый воздух, источники воды и хорошую окружающую среду, а также право подавать жалобы на загрязнение окружающей среды.</li><li><strong>Право на переустройство жилья</strong>: жильцы имеют право на разумное переустройство жилого пространства при условии невлияния на безопасность здания и права других.</li></ol><h2 id="iii-система-гарантии-жилья" tabindex="-1">III. Система гарантии жилья <a class="header-anchor" href="#iii-система-гарантии-жилья" aria-label="Permalink to &quot;III. Система гарантии жилья&quot;">​</a></h2><p>Система гарантии жилья Симбиотической Цивилизации Якоря делится на три типа жилья, охватывающих разные уровни потребностей:</p><table tabindex="0"><thead><tr><th>Тип</th><th>Название</th><th>Гарантируемая группа</th><th>Способ распределения</th><th>Аренда/цена</th></tr></thead><tbody><tr><td>Первый тип</td><td>Общественное арендное жильё</td><td>Группы с низким доходом, начинающие культиваторы, новые иммигранты</td><td>Система заявок и проверок, распределение в порядке очереди</td><td>Символически низкая аренда</td></tr><tr><td>Второй тип</td><td>Жильё с совместной собственностью</td><td>Группы со средним доходом, средние культиваторы</td><td>Система заявок и проверок, распределение по жребию</td><td>Ниже рыночной цены, совместная собственность индивида и государства</td></tr><tr><td>Третий тип</td><td>Коммерческое жильё</td><td>Группы с высоким доходом, продвинутые культиваторы</td><td>Рыночная сделка</td><td>Рыночная цена, с ограничениями регулирования</td></tr></tbody></table><p>Кроме того, с помощью технологии регулирования пространственных правовых принципов строятся «жилые зоны со свёрнутым пространством»: за счёт технологии пространственного сворачивания расширяется жилая площадь в ограниченном физическом пространстве, предоставляя больше жилых пространств районам высокой плотности. Жилые зоны со свёрнутым пространством должны проходить оценку безопасности для обеспечения пространственной стабильности.</p><h2 id="iv-адаптация-жилья-для-иных-рас" tabindex="-1">IV. Адаптация жилья для иных рас <a class="header-anchor" href="#iv-адаптация-жилья-для-иных-рас" aria-label="Permalink to &quot;IV. Адаптация жилья для иных рас&quot;">​</a></h2><p>С учётом особых жилищных потребностей различных рас во Вселенной Хэнъюань настоящий Закон устанавливает систему адаптации жилья для иных рас:</p><ul><li><strong>Водные расы</strong>: предоставление подводных жилых пространств или водно-сухопутных резиденций, оборудованных системами циркуляции воды и поддержания качества воды.</li><li><strong>Летающие расы</strong>: предоставление высотных жилых пространств или резиденций с взлётно-посадочными платформами, оборудованных управлением воздушным движением.</li><li><strong>Энергетические существа</strong>: предоставление жилых пространств с подходящей концентрацией энергии, оборудованных устройствами стабилизации энергии.</li><li><strong>Гигантские расы</strong>: предоставление крупномасштабных жилых пространств, строительные конструкции специально укреплены.</li><li><strong>Микроскопические расы</strong>: предоставление микроскопических жилых зон, оборудованных масштабирующими переходами и специальными объектами.</li></ul><p>Стандарты адаптации жилья для иных рас разрабатываются совместно компетентным органом по жилью и представителями всех рас, и регулярно обновляются.</p><h2 id="v-строительство-и-управление-жильем" tabindex="-1">V. Строительство и управление жильём <a class="header-anchor" href="#v-строительство-и-управление-жильем" aria-label="Permalink to &quot;V. Строительство и управление жильём&quot;">​</a></h2><ul><li><strong>Планирование строительства жилья</strong>: государство разрабатывает планы строительства жилья с учётом роста населения и иммиграции, обеспечивая баланс предложения и спроса на жильё.</li><li><strong>Строительные стандарты</strong>: строительство гарантированного жилья должно соответствовать стандартам безопасности, экологичности и пригодности для жизни; снижение качества строительства запрещено.</li><li><strong>Управление недвижимостью</strong>: жилые районы реализуют модель сочетания автономного управления и профессиональных услуг по недвижимости; жильцы имеют право участвовать в решениях по управлению недвижимостью.</li><li><strong>Ремонт жилья</strong>: ремонт гарантированного жилья осуществляется органом управления жильём, средства на ремонт выделяются из общественного фонда накопления.</li><li><strong>Механизм выхода</strong>: жильцы гарантированного жилья, чей доход или культивация превышают гарантийный стандарт, должны выйти из гарантированного жилья или перейти в коммерческое жильё, при этом предоставляется разумный переходный период.</li></ul><h2 id="vi-антиспекуляция-и-контроль" tabindex="-1">VI. Антиспекуляция и контроль <a class="header-anchor" href="#vi-антиспекуляция-и-контроль" aria-label="Permalink to &quot;VI. Антиспекуляция и контроль&quot;">​</a></h2><p>Для предотвращения спекуляции и хищничества в жилищной сфере настоящий Закон устанавливает следующие меры контроля:</p><ol><li>Ограничение количества коммерческого жилья, находящегося в собственности индивида; на превышение лимита взимается прогрессивный налог на недвижимость.</li><li>Запрет пересдачи и перепродажи гарантированного жилья; нарушители лишаются гарантийного статуса, жильё изымается.</li><li>Создание системы открытой информации о сделках с жильём, предотвращение закулисных операций и манипулирования ценами.</li><li>Квалификационное управление и контроль средств для застройщиков, предотвращение недостроев и мошенничества.</li><li>Создание механизмов жалоб и разрешения жилищных споров, защита законных прав и интересов жильцов.</li></ol><h2 id="vii-юридическая-ответственность" tabindex="-1">VII. Юридическая ответственность <a class="header-anchor" href="#vii-юридическая-ответственность" aria-label="Permalink to &quot;VII. Юридическая ответственность&quot;">​</a></h2><p>Действия, нарушающие положения настоящего Закона, в зависимости от тяжести обстоятельств несут следующую ответственность:</p><ul><li>Нарушение правил при распределении гарантированного жилья — предписание исправить и взыскание на ответственных лиц.</li><li>Пересдача или перепродажа гарантированного жилья — лишение гарантийного статуса, изъятие жилья и штраф.</li><li>Застройщики, снижающие качество строительства, — предписание переделать работы и штраф; при серьёзных обстоятельствах — лишение квалификации.</li><li>Спекуляция жильём — взимание высокого спекулятивного налога и штраф.</li><li>Сдача аварийного жилья, причинившая вред жильцам, — ответственность за возмещение; при серьёзных обстоятельствах — уголовная ответственность.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p><em>Закон о Гарантии Жилья</em> — реализация философии «дорога для каждого» Симбиотической Цивилизации Якоря в жилищной сфере. Создавая классифицированную систему гарантии жилья, расширяя жилое пространство с помощью пространственных правовых технологий, адаптируя жилищные потребности иных рас и борясь с жилищной спекуляцией, он гарантирует каждому существу безопасный, подходящий и стабильный дом, обеспечивая спокойное проживание для совместного продвижения Десяти Тысяч Рас.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Симбиотическая Конституция: Общие Принципы)</li><li>39-住房与环境保障 (Жильё и защита окружающей среды)</li><li>13-空间法理调度体系详解 (Подробное описание системы регулирования пространственных правовых принципов)</li><li>46-环境保护法 (Закон об Охране Окружающей Среды)</li></ul>',29)])])}const g=a(d,[["render",e]]);export{c as __pageData,g as default};
